#nullable enable
using Marten;
using Marten.AspNetCore;
using Wolverine.Http;
using HourBooking.Views;

namespace HourBooking.Slices.Booking;

/// <summary>
/// These belong to the <c>my-timesheet</c> and <c>my-projects</c> slices, which are still
/// <c>in-design</c> — their GWT tests are skipped. They exist here because the screen
/// <c>book-hours</c> owns cannot be built without them: the model says the Timesheet screen
/// <c>displays=</c> ten attributes, and a slice is not done end to end if nothing can read them back.
///
/// That is the honest tension in "one slice at a time": a State Change slice crosses screen → command
/// → event, and the screen reads a View that a neighbouring slice owns. Kept to the minimum — two
/// GETs, no rules — so promoting <c>my-timesheet</c> properly later means adding its GWTs, not
/// undoing this.
///
/// Both use <c>StreamOne</c>/<c>StreamMany</c> from Marten.AspNetCore: Marten's raw JSON goes straight
/// to the response without being deserialised into .NET objects and re-serialised, and the types carry
/// their own OpenAPI metadata.
/// </summary>
public static class TimesheetQueryEndpoints
{
    /// <summary>
    /// What the screen displays: month, monthStatus and every booking line with its dayTotal.
    /// 404 before the month has been started, which is the honest answer — the automation opens it.
    /// </summary>
    [WolverineGet("/timesheet/{employeeId}/{month}")]
    public static StreamOne<MyTimesheet> Get(Guid employeeId, string month, IQuerySession session)
        => new(session.Query<MyTimesheet>()
            .Where(x => x.Id == MyTimesheet.RowId(employeeId, month)));

    /// <summary>
    /// The projects an employee may book against, which is where projectName comes from — it is
    /// deliberately not on MyTimesheet, so the screen joins the two on projectId.
    /// Rows the employee has left are included and flagged, so the UI can explain a refusal rather
    /// than silently omitting the option.
    /// </summary>
    [WolverineGet("/timesheet/{employeeId}/projects")]
    public static StreamMany<MyProjects> Projects(Guid employeeId, IQuerySession session)
        => new(session.Query<MyProjects>()
            .Where(x => x.EmployeeId == employeeId)
            .OrderBy(x => x.ProjectName));
}
